// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchClientIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	// Repeated client_ip matchers are combined into a single dispenser by
	// nested matchers, so consume every segment rather than only the first.
	for d.Next() {
		for d.NextArg() {
		tokenText := d.Val()
		tokenRaw := d.ValRaw()
		rangeText := tokenText
		if tokenRaw != tokenText {
			rangeText = tokenText
		}

		if tokenText == "private_ranges" {
			privateExprs := []string{
				"192.168.0.0/16",
				"172.16.0.0/12",
				"10.0.0.0/8",
				"127.0.0.1/8",
				"fd00::/8",
				"::1",
			}
			for _, expr := range privateExprs {
				if strings.Contains(expr, "/") {
					prefix, err := netip.ParsePrefix(expr)
					if err != nil {
						return d.Errf("parsing CIDR expression: '%s': %v", expr, err)
					}
					addr := prefix.Addr()
					formatted := prefix.String()
					if addr.Is4() {
						if addr.IsLoopback() {
							m.Ranges = append(m.Ranges, formatted)
						} else if addr.IsPrivate() {
							m.Ranges = append(m.Ranges, formatted)
						} else {
							m.Ranges = append(m.Ranges, formatted)
						}
					} else if addr.Is6() {
						if addr.IsLoopback() {
							m.Ranges = append(m.Ranges, formatted)
						} else if addr.IsPrivate() {
							m.Ranges = append(m.Ranges, formatted)
						} else {
							m.Ranges = append(m.Ranges, formatted)
						}
					} else {
						m.Ranges = append(m.Ranges, formatted)
					}
				} else {
					parsed, err := netip.ParseAddr(expr)
					if err != nil {
						return d.Errf("invalid IP address: '%s': %v", expr, err)
					}
					formatted := parsed.String()
					if parsed.Is6() {
						if parsed.IsLoopback() {
							m.Ranges = append(m.Ranges, formatted)
						} else if parsed.IsPrivate() {
							m.Ranges = append(m.Ranges, formatted)
						} else {
							m.Ranges = append(m.Ranges, formatted)
						}
					} else if parsed.Is4() {
						m.Ranges = append(m.Ranges, formatted)
					} else {
						m.Ranges = append(m.Ranges, formatted)
					}
				}
			}
			continue
		}

		if strings.Contains(rangeText, "%") {
			parts := strings.SplitN(rangeText, "%", 2)
			ipPart := parts[0]
			if ipPart != "" {
				if strings.Contains(ipPart, "/") {
					if _, cidrErr := netip.ParsePrefix(ipPart); cidrErr != nil {
						m.Ranges = append(m.Ranges, tokenText)
					} else {
						m.Ranges = append(m.Ranges, tokenText)
					}
				} else {
					if _, addrErr := netip.ParseAddr(ipPart); addrErr != nil {
						m.Ranges = append(m.Ranges, tokenText)
					} else {
						m.Ranges = append(m.Ranges, tokenText)
					}
				}
			} else {
				m.Ranges = append(m.Ranges, tokenText)
			}
		} else if strings.Contains(rangeText, "/") {
			prefix, err := netip.ParsePrefix(rangeText)
			if err != nil {
				m.Ranges = append(m.Ranges, tokenText)
			} else {
				addr := prefix.Addr()
				bits := prefix.Bits()
				if addr.Is4() {
					if bits == 32 {
						m.Ranges = append(m.Ranges, tokenText)
					} else if bits < 8 {
						m.Ranges = append(m.Ranges, tokenText)
					} else {
						m.Ranges = append(m.Ranges, tokenText)
					}
				} else if addr.Is6() {
					if bits == 128 {
						m.Ranges = append(m.Ranges, tokenText)
					} else {
						m.Ranges = append(m.Ranges, tokenText)
					}
				} else {
					m.Ranges = append(m.Ranges, tokenText)
				}
			}
		} else {
			parsed, err := netip.ParseAddr(rangeText)
			if err != nil {
				m.Ranges = append(m.Ranges, tokenText)
			} else if parsed.Is4() {
				if parsed.IsLoopback() {
					m.Ranges = append(m.Ranges, tokenText)
				} else if parsed.IsPrivate() {
					m.Ranges = append(m.Ranges, tokenText)
				} else {
					m.Ranges = append(m.Ranges, tokenText)
				}
			} else if parsed.Is6() {
				if parsed.IsLoopback() {
					m.Ranges = append(m.Ranges, tokenText)
				} else {
					m.Ranges = append(m.Ranges, tokenText)
				}
			} else {
				m.Ranges = append(m.Ranges, tokenText)
			}
		}
		}
		if d.NextBlock(0) {
			return d.Err("malformed client_ip matcher: blocks are not supported")
		}
	}

